  "inlineSchema": "// Prisma Schema for Payment Collection Management System\n// Supports MariaDB / MySQL or SQLite fallback\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel User {\n  id            Int      @id @default(autoincrement())\n  username      String   @unique\n  password_hash String\n  name          String\n  role          String // ADMIN | SALESMAN\n  salesman_code String?\n  mobile        String?\n  email         String?\n  status        String   @default(\"ACTIVE\")\n  created_at    DateTime @default(now())\n  updated_at    DateTime @updatedAt\n\n  createdFollowups Followup[]\n  createdPayments  Payment[]\n  whatsappLogs     WhatsappLog[]\n\n  @@map(\"users\")\n}\n\nmodel Customer {\n  id               Int      @id @default(autoincrement())\n  customer_code    String   @unique\n  customer_name    String\n  alias            String?\n  address          String?\n  city             String?\n  state            String?\n  gstin            String?\n  contact_person   String?\n  mobile           String?\n  alternate_mobile String?\n  email            String?\n  salesman_code    String?\n  credit_limit     Float    @default(0)\n  credit_days      Int      @default(0)\n  status           String   @default(\"ACTIVE\")\n  created_at       DateTime @default(now())\n  updated_at       DateTime @updatedAt\n\n  invoices     Invoice[]\n  payments     Payment[]\n  followups    Followup[]\n  whatsappLogs WhatsappLog[]\n\n  @@index([customer_code])\n  @@index([salesman_code])\n  @@index([mobile])\n  @@map(\"customers\")\n}\n\nmodel Invoice {\n  id                  Int       @id @default(autoincrement())\n  invoice_number      String    @unique\n  invoice_date        DateTime\n  customer_id         Int\n  salesman_code       String?\n  invoice_amount      Float\n  paid_amount         Float     @default(0)\n  outstanding_amount  Float\n  due_date            DateTime\n  source_voucher_code String?\n  status              String    @default(\"NOT_DUE\") // NOT_DUE, DUE_TODAY, OVERDUE, PARTIALLY_PAID, PAID\n  imported_at         DateTime? @default(now())\n  updated_at          DateTime  @updatedAt\n\n  customer  Customer      @relation(fields: [customer_id], references: [id], onDelete: Cascade)\n  items     InvoiceItem[]\n  payments  Payment[]\n  followups Followup[]\n\n  @@index([invoice_number])\n  @@index([salesman_code])\n  @@index([invoice_date])\n  @@index([due_date])\n  @@index([outstanding_amount])\n  @@map(\"invoices\")\n}\n\nmodel InvoiceItem {\n  id         Int     @id @default(autoincrement())\n  invoice_id Int\n  item_name  String\n  hsn        String?\n  quantity   Float\n  unit       String?\n  rate       Float\n  discount   Float   @default(0)\n  tax        Float   @default(0)\n  amount     Float\n\n  invoice Invoice @relation(fields: [invoice_id], references: [id], onDelete: Cascade)\n\n  @@map(\"invoice_items\")\n}\n\nmodel Payment {\n  id               Int      @id @default(autoincrement())\n  customer_id      Int\n  invoice_id       Int?\n  payment_date     DateTime\n  amount           Float\n  payment_mode     String // Cash, Cheque, NEFT, RTGS, IMPS, UPI, Other\n  reference_number String?\n  bank             String?\n  remark           String?\n  created_by       Int?\n  created_at       DateTime @default(now())\n\n  customer Customer @relation(fields: [customer_id], references: [id], onDelete: Cascade)\n  invoice  Invoice? @relation(fields: [invoice_id], references: [id], onDelete: SetNull)\n  user     User?    @relation(fields: [created_by], references: [id], onDelete: SetNull)\n\n  @@map(\"payments\")\n}\n\nmodel Followup {\n  id                      Int       @id @default(autoincrement())\n  customer_id             Int\n  invoice_id              Int?\n  salesman_code           String?\n  followup_date           DateTime\n  followup_time           String?\n  followup_type           String // Phone Call, WhatsApp, Visit, Email, Payment Commitment, Payment Received, Other\n  status                  String    @default(\"Pending\") // Pending, Completed, Payment Promised, Payment Received, Customer Not Responding, Dispute, Postponed, Cancelled\n  expected_payment_date   DateTime?\n  expected_payment_amount Float?\n  promise_to_pay_date     DateTime?\n  promise_to_pay_amount   Float?\n  remark                  String?\n  next_followup_date      DateTime?\n  next_followup_time      String?\n  priority                String    @default(\"Medium\") // Low, Medium, High, Urgent\n  attachment              String?\n  created_by              Int?\n  created_at              DateTime  @default(now())\n  updated_at              DateTime  @updatedAt\n\n  customer Customer @relation(fields: [customer_id], references: [id], onDelete: Cascade)\n  invoice  Invoice? @relation(fields: [invoice_id], references: [id], onDelete: SetNull)\n  user     User?    @relation(fields: [created_by], references: [id], onDelete: SetNull)\n\n  @@index([salesman_code])\n  @@index([followup_date])\n  @@map(\"followups\")\n}\n\nmodel WhatsappLog {\n  id          Int      @id @default(autoincrement())\n  customer_id Int\n  mobile      String\n  message     String\n  invoice_ids String?\n  sent_by     Int?\n  sent_at     DateTime @default(now())\n  status      String   @default(\"SENT\")\n\n  customer Customer @relation(fields: [customer_id], references: [id], onDelete: Cascade)\n  user     User?    @relation(fields: [sent_by], references: [id], onDelete: SetNull)\n\n  @@map(\"whatsapp_logs\")\n}\n\nmodel ImportLog {\n  id               Int       @id @default(autoincrement())\n  started_at       DateTime  @default(now())\n  completed_at     DateTime?\n  total_records    Int       @default(0)\n  inserted_records Int       @default(0)\n  updated_records  Int       @default(0)\n  failed_records   Int       @default(0)\n  status           String    @default(\"RUNNING\") // RUNNING, SUCCESS, FAILED\n  error_message    String?\n\n  @@map(\"import_logs\")\n}\n\nmodel MssqlConfig {\n  id                       Int      @id @default(1)\n  host                     String   @default(\"localhost\")\n  port                     Int      @default(1433)\n  database_name            String   @default(\"BUSY_ERP_DB\")\n  username                 String   @default(\"sa\")\n  password_encrypted       String   @default(\"\")\n  encrypt                  Boolean  @default(false)\n  trust_server_certificate Boolean  @default(true)\n  import_sql               String   @default(\"SELECT VOU_NO, VOUCHER_DATE, PARTY, ALIAS, ADDRESS, CITY, STATE, GSTIN, MOBILE, SALESMAN, ITEM_NAME, HSN, QTY, RATE, TAX, DISC, TOTAL_AMOUNT, DUE_DATE FROM VOUCHERS WHERE VOUCHER_DATE >= @startdate@ AND VOUCHER_DATE <= @enddate@\")\n  updated_at               DateTime @updatedAt\n\n  @@map(\"mssql_configs\")\n}\n\nmodel WhatsappTemplate {\n  id         Int      @id @default(autoincrement())\n  name       String   @unique // Payment Reminder, Payment Due, Payment Commitment, Custom\n  content    String\n  is_default Boolean  @default(false)\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  @@map(\"whatsapp_templates\")\n}\n",
